impl ServerHandler for DurableServer {
    fn get_task(&self, request: GetTaskParams, context: RequestContext<RoleServer>) -> impl Future<Output = Result<GetTaskResult, McpError>> + MaybeSendFuture + '_ {
        async move {
            let principal = authenticated_principal(&context)?;
            let row = self.store.get_authorized(&request, &principal).await?;
            let payload: TaskPayload = self.store.reconstruct_task_payload(&row)?;
            let mut task = Task::new(
                row.task_id.clone(),
                payload.status(),
                row.created_at.clone(),
                row.last_updated_at.clone(),
            );
            if let Some(message) = row.status_message.clone() { task = task.with_status_message(message); }
            if let Some(ttl_ms) = row.ttl_ms { task = task.with_ttl_ms(ttl_ms); }
            if let Some(poll_interval_ms) = row.poll_interval_ms { task = task.with_poll_interval_ms(poll_interval_ms); }
            Ok(GetTaskResult::new(DetailedTask::new(task, payload)))
        }
    }
}
